shellCommands.command:
(npx next start -p 3111 > /tmp/next.log 2>&1 &) ; sleep 6; 
echo "--- / (SSR)"; curl -s localhost:3111/ | grep -o "Your user agent: [^<]*\|<title>[^<]*</title>";
echo "--- /blog"; curl -s -o /dev/null -w "%{http_code}\n" localhost:3111/blog;
echo "--- /blog/1"; curl -s -o /dev/null -w "%{http_code}\n" localhost:3111/blog/1;
echo "--- /blog/500 (on-demand)"; curl -s -o /dev/null -w "%{http_code}\n" localhost:3111/blog/500;
echo "--- /blog/99999 (notFound)"; curl -s -w " code=%{http_code}\n" localhost:3111/blog/99999 | grep -o "404 - Page Not Found\|code=[0-9]*";
echo "--- /nope"; curl -s -o /dev/null -w "%{http_code}\n" localhost:3111/nope;

echo "GET /api/posts:"; curl -s localhost:3111/api/posts;
echo -e "\nPOST valid:"; curl -s -X POST localhost:3111/api/posts -H 'content-type: application/json' -d '{"title":"t","content":"c"}' -w " [%{http_code}]";
echo -e "\nPOST missing fields:"; curl -s -X POST localhost:3111/api/posts -H 'content-type: application/json' -d '{}' -w " [%{http_code}]";
echo -e "\nPOST bad json:"; curl -s -X POST localhost:3111/api/posts -H 'content-type: application/json' -d 'notjson' -w " [%{http_code}]";
echo -e "\nDELETE /api/posts (unsupported):"; curl -s -i -X DELETE localhost:3111/api/posts | head -3;
echo -e "\nGET /api/posts/7:"; curl -s localhost:3111/api/posts/7 -w " [%{http_code}]";
echo -e "\nPUT /api/posts/7:"; curl -s -X PUT localhost:3111/api/posts/7 -H 'content-type: application/json' -d '{"title":"new"}' -w " [%{http_code}]";
echo -e "\nDELETE /api/posts/7:"; curl -s -X DELETE localhost:3111/api/posts/7 -w " [%{http_code}]";
echo -e "\nPATCH /api/posts/7 (unsupported):"; curl -s -i -X PATCH localhost:3111/api/posts/7 | head -4
